import * as React from "react"
import { color, stage, type Orientation } from "../lib/tokens"
import { Label } from "../ui/label"
import { Big } from "../ui/big"
import { Chip } from "../ui/chip"
import { StatCard } from "../ui/stat-card"
import { Callout } from "../ui/callout"
import { BulletList } from "../ui/bullet-list"
import { Brand } from "../ui/brand"
import { Scene } from "./scene"
import { Pop, Leave } from "./pop"
import { CodeCard } from "./code-card"
import { RebuildScreens } from "./rebuild-screens"
import { Catalog } from "./catalog"
import { Propagate } from "./propagate"
import { Shelf, Twice } from "./shelf"
import type { At, Block, SceneSpec, SafeArea } from "./spec"

/**
 * Compile a SceneSpec into a Remotion scene for one orientation.
 *
 * Layout is a vertical flow inside the stage's safe area (tokens.stage): blocks stack top to bottom
 * with `gap` between them. Explicit composition options and orientation variants let authors
 * design for each frame; content is not automatically fitted. By default, a block changes shape: a stat-row is three cards
 * side by side in landscape and three row-mode cards stacked in vertical; text sizes step down.
 *
 * `resolve(phrase)` returns seconds from scene start for a narration phrase (the host's `rel`);
 * `t(s)` translates an on-screen string (the host's i18n). Both are injected so the compiler knows
 * nothing about a project's timing table or dictionary.
 */
export type Host = {
  resolve: (phrase: string) => number
  t?: (s: string) => string
}

const pick = <T,>(v: T | { landscape: T; vertical: T }, o: Orientation): T =>
  typeof v === "object" && v !== null && "landscape" in (v as object)
    ? (v as { landscape: T; vertical: T })[o]
    : (v as T)

/** "name", "name+0.2", "name-0.5", or a number of seconds. */
export function resolveAt(at: At, spec: SceneSpec, host: Host): number {
  if (typeof at === "number") {
    if (!Number.isFinite(at))
      throw new Error(`scene ${spec.id}: non-finite time`)
    return at
  }
  const m = /^([\w-]+?)\s*([+-]\s*(?:\d+(?:\.\d+)?|\.\d+))?$/.exec(at.trim())
  if (!m) throw new Error(`scene ${spec.id}: bad anchor "${at}"`)
  const exact = spec.anchors?.[at.trim()]
  const phrase = exact ?? spec.anchors?.[m[1]]
  if (phrase === undefined)
    throw new Error(`scene ${spec.id}: unknown anchor "${m[1]}"`)
  const off =
    exact === undefined && m[2] ? parseFloat(m[2].replace(/\s+/g, "")) : 0
  const result = host.resolve(phrase) + off
  if (!Number.isFinite(result))
    throw new Error(`scene ${spec.id}: non-finite anchor "${at}"`)
  return result
}

/** Resolve explicit canvas insets while retaining legacy geometry for existing scenes. */
export function sceneGeometry(
  orientation: Orientation,
  safeArea: SafeArea = "legacy"
) {
  const s = stage[orientation]
  const insets =
    typeof safeArea === "object"
      ? safeArea
      : safeArea === "legacy"
        ? { left: s.pad, right: s.pad, top: s.top, bottom: s.h - s.bottom }
        : safeArea === "social" && orientation === "vertical"
          ? { left: 72, right: 160, top: 160, bottom: 320 }
          : { left: s.pad, right: s.pad, top: s.top, bottom: s.top }
  if (
    [insets.left, insets.right, insets.top, insets.bottom].some(
      (v) => !Number.isFinite(v) || v < 0
    ) ||
    insets.left + insets.right >= s.w ||
    insets.top + insets.bottom >= s.h
  )
    throw new Error("Invalid scene safe-area insets")
  return {
    left: insets.left,
    top: insets.top,
    width: s.w - insets.left - insets.right,
    height: s.h - insets.top - insets.bottom,
  }
}

export function SceneFromSpec({
  spec,
  orientation,
  host,
  showSafeArea = false,
}: {
  spec: SceneSpec
  showSafeArea?: boolean
  orientation: Orientation
  host: Host
}) {
  const options = { ...spec.composition, ...spec.variants?.[orientation] }
  const area = sceneGeometry(orientation, options.safeArea)
  const layout = options.layout ?? "flow"
  const blocks = options.blocks ?? spec.blocks
  const subjectScale = options.subjectScale ?? 1
  if (!Number.isFinite(subjectScale) || subjectScale <= 0)
    throw new Error("subjectScale must be positive and finite")
  const ratio = options.headlineRatio ?? 0.25
  if (!Number.isFinite(ratio) || ratio <= 0 || ratio >= 1)
    throw new Error("headlineRatio must be between 0 and 1")
  if (layout === "headline-illustration" && (blocks.length !== 2 || spec.title))
    throw new Error(
      "headline-illustration requires exactly two blocks and no title"
    )
  const V = orientation === "vertical"
  const W = area.width
  const H = area.height
  const tr = host.t ?? ((x: string) => x)
  const at = (a: At) => resolveAt(a, spec, host)
  const gap = pick(options.gap ?? spec.gap ?? 40, orientation)
  const tone = (c?: "accent" | "ink") =>
    c === "ink" ? color.ink : color.accent

  const render = (
    b: Block,
    i: number,
    height = H,
    width = W
  ): React.ReactNode => {
    const body = renderBody(b, i, height, width)
    return b.until === undefined || b.type === "overlay" ? (
      body
    ) : (
      <Leave key={i} at={at(b.until)}>
        {body}
      </Leave>
    )
  }

  const renderBody = (
    b: Block,
    i: number,
    height: number,
    W: number
  ): React.ReactNode => {
    switch (b.type) {
      case "big":
        return (
          <Pop key={i} at={at(b.at)} from={b.from ?? "up"} style={{ width: W }}>
            <Big
              size={b.size ?? (V ? 96 : 120)}
              color={b.color ? tone(b.color) : color.ink}
              style={{
                whiteSpace: "pre-line",
                textAlign: b.align === "center" ? "center" : undefined,
              }}
            >
              {tr(b.text)}
            </Big>
          </Pop>
        )
      case "stat-row": {
        const n = b.items.length
        if (n === 0) return null
        const cw = V ? W : Math.floor((W - 40 * (n - 1)) / n)
        return (
          <div
            key={i}
            style={{
              display: "flex",
              flexDirection: V ? "column" : "row",
              gap: V ? 30 : 40,
            }}
          >
            {b.items.map((it, k) => (
              <Pop key={k} at={at(it.at)} from="up">
                <StatCard
                  row={V}
                  w={cw}
                  h={V ? 180 : 300}
                  label={tr(it.label)}
                  value={tr(it.value)}
                  sub={it.sub ? tr(it.sub) : undefined}
                  valueColor={tone(it.valueColor)}
                />
              </Pop>
            ))}
          </div>
        )
      }
      case "note":
        return (
          <Pop key={i} at={at(b.at)} from="left" style={{ width: W }}>
            <Callout variant="note" size={V ? 22 : 24}>
              {tr(b.text)}
            </Callout>
          </Pop>
        )
      case "callout":
        return (
          <Pop key={i} at={at(b.at)} from="up" style={{ width: W }}>
            <Callout
              variant={b.variant ?? "accent"}
              size={V ? 30 : 34}
              maxWidth={W}
            >
              {tr(b.text)}
            </Callout>
          </Pop>
        )
      case "bullets": {
        const t0 = at(b.at)
        const step = b.step ?? 0.6
        return (
          <BulletList
            key={i}
            items={b.items.map(tr)}
            marker={b.marker}
            size={36}
            gap={V ? 22 : 16}
            style={{ width: W }}
            renderItem={(node, k) => (
              <Pop at={t0 + k * step} from="left" dist={14}>
                {node}
              </Pop>
            )}
          />
        )
      }
      case "chips": {
        const t0 = at(b.at)
        return (
          <div
            key={i}
            style={{ display: "flex", gap: 14, flexWrap: "wrap", width: W }}
          >
            {b.items.map((c, k) => (
              <Pop key={k} at={t0 + k * (b.step ?? 0.35)} from="up" dist={12}>
                <Chip size={V ? 28 : 26} accent={b.accent} mono={b.mono}>
                  {tr(c)}
                </Chip>
              </Pop>
            ))}
          </div>
        )
      }
      case "code": {
        const cc = {
          green: color.codeGreen,
          soft: color.soft,
          dim: color.dimOnDark,
        } as const
        return (
          <Pop key={i} at={at(b.at)} from="up">
            <CodeCard
              charsPerSecond={b.charsPerSecond}
              title={b.title ? tr(b.title) : undefined}
              w={V ? W : Math.min(W, 1200)}
              h={
                layout === "illustration" || layout === "headline-illustration"
                  ? height
                  : V
                    ? 520
                    : 480
              }
              size={V ? 26 : 24}
              lines={b.lines.map((l) => ({
                t: tr(l.text),
                at: at(l.at),
                color: l.color ? cc[l.color] : undefined,
              }))}
            />
          </Pop>
        )
      }
      case "spacer":
        return <div key={i} style={{ height: pick(b.h, orientation) }} />
      case "screens":
        return (
          <RebuildScreens
            key={i}
            phoneScale={b.phoneScale}
            w={W}
            h={pick(
              b.h ??
                (layout === "flow"
                  ? { landscape: 720, vertical: 1000 }
                  : height),
              orientation
            )}
            pieces={b.pieces.map((p) => ({ kind: p.kind, at: at(p.at) }))}
            again={(b.again ?? []).map(at)}
            sticker={
              b.sticker
                ? { text: tr(b.sticker.text), at: at(b.sticker.at) }
                : undefined
            }
          />
        )
      case "catalog":
        return (
          <Catalog
            key={i}
            w={V ? W : Math.min(W, 1200)}
            at={at(b.at)}
            title={b.title ? tr(b.title) : undefined}
            items={b.items.map((it) => ({
              kind: it.kind,
              label: tr(it.label),
              at: at(it.at),
            }))}
            tokens={(b.tokens ?? []).map((tk) => ({
              kind: tk.kind,
              label: tr(tk.label),
              at: at(tk.at),
            }))}
            tokensAt={b.tokensAt === undefined ? undefined : at(b.tokensAt)}
            stamp={
              b.stamp
                ? { text: tr(b.stamp.text), at: at(b.stamp.at) }
                : undefined
            }
          />
        )
      case "propagate": {
        const opt = (a?: At) => (a === undefined ? undefined : at(a))
        return (
          <Propagate
            key={i}
            w={W}
            h={pick(
              b.h ??
                (layout === "flow"
                  ? { landscape: 760, vertical: 1040 }
                  : height),
              orientation
            )}
            at={at(b.at)}
            label={
              b.label
                ? { text: tr(b.label.text), at: at(b.label.at) }
                : undefined
            }
            targets={b.targets}
            bug={opt(b.bug)}
            fix={opt(b.fix)}
            fixed={opt(b.fixed)}
            recolor={opt(b.recolor)}
            recolored={opt(b.recolored)}
          />
        )
      }
      case "shelf":
        return (
          <Shelf
            key={i}
            w={V ? W : Math.min(W, 1100)}
            items={b.items.map((it) => ({
              text: tr(it.text),
              at: at(it.at),
              tone: it.tone,
            }))}
          />
        )
      case "twice":
        return (
          <Twice
            key={i}
            w={V ? W : Math.min(W, 1000)}
            at={at(b.at)}
            second={at(b.second)}
            strike={b.strike === undefined ? undefined : at(b.strike)}
          />
        )
      case "brand":
        return (
          <Pop key={i} at={at(b.at)} from="up" dist={20} style={{ width: W }}>
            <Brand
              size={b.size ?? (V ? 56 : 52)}
              tagline={b.tagline ? tr(b.tagline) : undefined}
            />
          </Pop>
        )
      case "overlay":
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: W,
              height,
              display: "flex",
              flexDirection: "column",
              justifyContent:
                (b.valign ?? "center") === "center" ? "center" : undefined,
              gap,
            }}
          >
            {b.until === undefined ? (
              b.blocks.map((block, index) => render(block, index, height, W))
            ) : (
              <Leave
                at={at(b.until)}
                style={{ display: "flex", flexDirection: "column", gap }}
              >
                {b.blocks.map((block, index) => render(block, index, height))}
              </Leave>
            )}
          </div>
        )
    }
  }

  const subject = (block: Block, index: number, height: number) => (
    <div style={{ width: W, height, position: "relative", flexShrink: 0 }}>
      <div
        style={{
          width: W / subjectScale,
          height: height / subjectScale,
          transform: "scale(" + subjectScale + ")",
          transformOrigin: "top left",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          position: "relative",
        }}
      >
        {render(block, index, height / subjectScale, W / subjectScale)}
      </div>
    </div>
  )
  if (layout === "illustration" && (blocks.length !== 1 || spec.title))
    throw new Error("illustration requires exactly one block and no title")
  if (!Number.isFinite(gap) || gap < 0 || gap >= H)
    throw new Error("gap must fit inside the safe area")
  return (
    <Scene>
      <div
        style={{
          position: "absolute",
          left: area.left,
          top: area.top,
          width: W,
          maxHeight: H,
          height:
            layout !== "flow" || (options.valign ?? spec.valign) === "center"
              ? H
              : undefined,
          justifyContent:
            layout === "hero" ||
            layout === "illustration" ||
            (options.valign ?? spec.valign) === "center"
              ? "center"
              : undefined,
          display: "flex",
          flexDirection: "column",
          gap,
        }}
      >
        {spec.title ? (
          <Pop at={0.1} style={{ marginBottom: V ? 0 : 30 }}>
            <Label>{tr(spec.title)}</Label>
          </Pop>
        ) : null}
        {layout === "headline-illustration"
          ? blocks.map((block, index) => {
              const height = (H - gap) * (index === 0 ? ratio : 1 - ratio)
              return (
                <div
                  key={index}
                  style={{
                    position: "relative",
                    height,
                    flexShrink: 0,
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                  }}
                >
                  {index === 0
                    ? render(block, index, height)
                    : subject(block, index, height)}
                </div>
              )
            })
          : layout === "illustration"
            ? subject(blocks[0], 0, H)
            : blocks.map((block, index) => render(block, index))}
        {showSafeArea && (
          <div
            aria-hidden
            style={{
              position: "absolute",
              inset: 0,
              height: H,
              outline: "3px dashed " + color.accent,
              pointerEvents: "none",
            }}
          />
        )}
      </div>
    </Scene>
  )
}

/**
 * Scene spec: the YAML shape a scene is written in. One spec compiles to both orientations.
 *
 * Timing: every `at` is an anchor NAME (a key of `anchors`), optionally with an offset: "posible+0.2".
 * Anchors map to a phrase in the narration; the host resolves them with its own timing table
 * (see `compile.tsx`, `resolve`). Numbers are also accepted as literal seconds from scene start.
 *
 * Text: every string that is shown on screen passes through the host's `t()` so one spec serves
 * every language; keys are the source-language strings (Spanish in tacosdedatos videos).
 *
 * The JSDoc below is the field reference: these types generate the JSON Schema served at
 * https://jbm-ui.bns.studio/schemas/scene-spec.json. Sizes are canvas pixels; times are seconds.
 */

/**
 * A time. A number is seconds from scene start. A string is an anchor name, optionally followed by
 * a signed offset in seconds: "explain", "explain+0.2", "explain-0.5". An anchor whose own name
 * contains the offset text (e.g. "my-cue-0.5") matches exactly first.
 * @pattern ^\s*[\w-]+?\s*([+-]\s*(\d+(\.\d+)?|\.\d+))?\s*$
 */
export type At = string | number

/** A pixel value that can differ per orientation. */
export type PerOrientation = {
  /**
   * Pixels on the 1920 × 1080 stage.
   * @minimum 0
   */
  landscape: number
  /**
   * Pixels on the 1080 × 1920 stage.
   * @minimum 0
   */
  vertical: number
}

export type StatItem = {
  /** Entrance time of this card. */
  at: At
  /** Small caption above the value; translated. */
  label: string
  /** The figure itself, as display text ("42 %"); translated. */
  value: string
  /** Optional line under the value; translated. */
  sub?: string
  /**
   * Value color.
   * @default "accent"
   */
  valueColor?: "accent" | "ink"
}

/** Any block may leave the screen on a cue: it fades out and drifts up from `until`. */
export type Exit = {
  /** Exit time: the block fades out and drifts up over 0.4 s. Flow blocks keep their layout space. */
  until?: At
}

export type Block = BlockBody & Exit

export type BlockBody =
  | {
      /** Headline text in the display face. */
      type: "big"
      /** Entrance time. */
      at: At
      /** Headline; `\n` breaks lines. Translated. */
      text: string
      /** Text color; omit for ink. */
      color?: "accent" | "ink"
      /**
       * Font size in px; positive. Default 120 in landscape, 96 in vertical.
       * @exclusiveMinimum 0
       */
      size?: number
      /**
       * Entrance motion.
       * @default "up"
       */
      from?: "up" | "scale" | "left"
      /**
       * Text alignment.
       * @default "left"
       */
      align?: "left" | "center"
    }
  | {
      /** Stat cards: side by side (300 px tall) in landscape, stacked row cards (180 px) in vertical. */
      type: "stat-row"
      /** One card per item, each with its own entrance cue; an empty list renders nothing. */
      items: StatItem[]
    }
  | {
      /** A small annotation (Callout note variant, 24 px landscape / 22 px vertical) sliding in from the left. */
      type: "note"
      /** Entrance time. */
      at: At
      /** Annotation text; translated. */
      text: string
    }
  | {
      /** A boxed statement (30–34 px). */
      type: "callout"
      /** Entrance time. */
      at: At
      /** Statement text; translated. */
      text: string
      /**
       * Box style.
       * @default "accent"
       */
      variant?: "accent" | "ink"
    }
  | {
      /** A 36 px bullet list; items enter one after another. */
      type: "bullets"
      /** Entrance time of the first item. */
      at: At
      /** Item texts; translated. */
      items: string[]
      /**
       * Seconds between item entrances.
       * @default 0.6
       * @minimum 0
       */
      step?: number
      /**
       * Bullet marker.
       * @default "arrow"
       */
      marker?: "arrow" | "dot"
    }
  | {
      /** A wrapping row of chips that enter one after another. */
      type: "chips"
      /** Entrance time of the first chip. */
      at: At
      /** Chip texts; translated. */
      items: string[]
      /**
       * Seconds between chip entrances.
       * @default 0.35
       * @minimum 0
       */
      step?: number
      /**
       * Vermilion chips.
       * @default false
       */
      accent?: boolean
      /**
       * Monospace chip text.
       * @default false
       */
      mono?: boolean
    }
  | {
      /** A dark code card whose lines type in place. 480 px tall in landscape flow (max 1200 wide), 520 px in vertical. */
      type: "code"
      /** Card entrance time; set line cues at or after it. */
      at: At
      /** File name in the card header; translated. */
      title?: string
      /**
       * Typing speed in characters per second; positive and finite.
       * @default 32
       * @exclusiveMinimum 0
       */
      charsPerSecond?: number
      /** Code lines. Each starts typing at the later of its `at` and the end of the previous line. */
      lines: {
        /** Line text, typed character by character; translated. */
        text: string
        /** Earliest typing start for this line. */
        at: At
        /** Line color; omit for the default code color. */
        color?: "green" | "soft" | "dim"
      }[]
    }
  | {
      /** Empty vertical space. */
      type: "spacer"
      /**
       * Height in px, or per orientation; nonnegative.
       * @minimum 0
       */
      h: number | PerOrientation
    }
  /** Illustrated blocks (paper cut-out pieces of interface drawn with the UI Bits items). */
  | {
      /** A phone screen built piece by piece, then rebuilt on new screens on every `again` cue. */
      type: "screens"
      /** Interface pieces placed on the phone, each on its own cue. */
      pieces: {
        /** Piece shape. */
        kind: "button" | "input" | "card"
        /** Placement time. */
        at: At
      }[]
      /** Each cue starts a new screen that rebuilds the same pieces. */
      again?: At[]
      /**
       * Phone size multiplier; capped against the available box.
       * @default 1
       * @exclusiveMinimum 0
       */
      phoneScale?: number
      /** A sticker slapped on the pile. */
      sticker?: {
        /** Sticker text; translated. */
        text: string
        /** Sticker time. */
        at: At
      }
      /**
       * Block height in px; positive. Default 720 landscape / 1000 vertical in flow; the allocated height in illustration layouts.
       * @exclusiveMinimum 0
       */
      h?: number | PerOrientation
    }
  | {
      /** A catalogue sheet of pieces (top row) and design-token glyphs (second row). */
      type: "catalog"
      /** Sheet entrance time. */
      at: At
      /** Sheet heading; translated. */
      title?: string
      /** Interface pieces on the top row, each on its own cue. */
      items: {
        /** Piece shape. */
        kind: "button" | "input" | "card"
        /** Caption; translated. */
        label: string
        /** Entrance time. */
        at: At
      }[]
      /** Design-token glyphs on the second row. */
      tokens?: {
        /** Glyph kind. */
        kind: "color" | "type" | "space"
        /** Caption; translated. */
        label: string
        /** Entrance time. */
        at: At
      }[]
      /** When the sheet unfolds to show the token row (default: first token cue − 0.6 s). */
      tokensAt?: At
      /** A stamp pressed onto the sheet. */
      stamp?: {
        /** Stamp text; translated. */
        text: string
        /** Stamp time. */
        at: At
      }
    }
  | {
      /** One source card fanning out to a grid of screens; bug/fix/recolor cues propagate along the lines. */
      type: "propagate"
      /** Entrance time of the source card. */
      at: At
      /** Caption over the source card. */
      label?: {
        /** Caption text; translated. */
        text: string
        /** Caption time. */
        at: At
      }
      /**
       * Number of target screens; a positive integer.
       * @default 6
       * @minimum 1
       * @integer
       */
      targets?: number
      /** A bug appears on the source and travels to every target. */
      bug?: At
      /** The fix leaves the source; `fixed` (later) is when it arrives. */
      fix?: At
      /** Arrival of the fix; must be later than `fix`. */
      fixed?: At
      /** A recolor leaves the source; `recolored` (later) is when it arrives. */
      recolor?: At
      /** Arrival of the recolor; must be later than `recolor`. */
      recolored?: At
      /**
       * Block height in px; positive. Default 760 landscape / 1040 vertical in flow; the allocated height in illustration layouts.
       * @exclusiveMinimum 0
       */
      h?: number | PerOrientation
    }
  | {
      /** A pile of wide library cards, each on its own cue; `tone: accent` for the one that is yours. */
      type: "shelf"
      /** Cards from top to bottom. */
      items: {
        /** Card text; translated. */
        text: string
        /** Entrance time. */
        at: At
        /**
         * Card paper.
         * @default "paper"
         */
        tone?: "paper" | "accent" | "ink"
      }[]
    }
  | {
      /** A button, the same button again, and a vermilion cross over the second. */
      type: "twice"
      /** First button time. */
      at: At
      /** Second (duplicate) button time. */
      second: At
      /** Time the cross strikes the second button. */
      strike?: At
    }
  | {
      /** The jbm brand lockup. */
      type: "brand"
      /** Entrance time. */
      at: At
      /** Line under the lockup; translated. */
      tagline?: string
      /**
       * Lockup size in px; positive. Default 52 in landscape, 56 in vertical.
       * @exclusiveMinimum 0
       */
      size?: number
    }
  | {
      /** A layer over the flow: its blocks stack in their own centred column inside the safe area, so a
       *  late beat can take the middle of the screen after earlier blocks `until`-exit. */
      type: "overlay"
      /** Nested blocks, stacked with the scene gap. */
      blocks: Block[]
      /**
       * Vertical placement of the nested stack.
       * @default "center"
       */
      valign?: "top" | "center"
    }

/**
 * Canvas-pixel insets on a 1920 × 1080 (landscape) or 1080 × 1920 (vertical) composition.
 * "legacy": landscape 90/120/160/120, vertical 100/72/480/72 (top/right/bottom/left).
 * "full": landscape 90/120/90/120, vertical 100/72/100/72.
 * "social": vertical 160/160/320/72; in landscape it falls back to "full".
 * Custom insets must be nonnegative finite numbers that leave a positive content area.
 */
export type SafeArea =
  | "legacy"
  | "full"
  | "social"
  | {
      /** @minimum 0 */
      top: number
      /** @minimum 0 */
      right: number
      /** @minimum 0 */
      bottom: number
      /** @minimum 0 */
      left: number
    }
/**
 * "flow" stacks blocks top to bottom. "hero" centers the stack. "headline-illustration" takes
 * exactly two blocks and no scene title (headline, then subject). "illustration" takes exactly one
 * subject block and no scene title.
 */
export type SceneLayout =
  "flow" | "hero" | "headline-illustration" | "illustration"
export type CompositionOptions = {
  /**
   * Insets are canvas pixels. Social is a house preset, not a platform guarantee.
   * @default "legacy"
   */
  safeArea?: SafeArea
  /**
   * How blocks are placed in the safe area.
   * @default "flow"
   */
  layout?: SceneLayout
  /**
   * Fraction reserved for the first block in headline-illustration (default .25); strictly between 0 and 1.
   * @default 0.25
   * @exclusiveMinimum 0
   * @exclusiveMaximum 1
   */
  headlineRatio?: number
  /**
   * Illustration subject scale; its logical box shrinks to preserve the safe area.
   * @default 1
   * @exclusiveMinimum 0
   */
  subjectScale?: number
  /**
   * Gap between blocks in px (per orientation allowed); overrides the scene `gap`. Nonnegative.
   * @minimum 0
   */
  gap?: number | PerOrientation
  /** Vertical placement of the flow stack; overrides the scene `valign`. */
  valign?: "top" | "center"
  /** Overrides replace the entire block list; anchors remain shared. */
  blocks?: Block[]
}

export type SceneSpec = {
  /** Scene identifier; appears in error messages. */
  id: string
  /** Composition options shared by both orientations. */
  composition?: Omit<CompositionOptions, "blocks">
  /** Per-orientation composition options; they override `composition` key by key. */
  variants?: Partial<Record<"landscape" | "vertical", CompositionOptions>>
  /** Scene heading (Label, top-left). Omit for a headline-only scene. */
  title?: string
  /**
   * First words the narrator says in this scene, for a host that cuts scene boundaries from a
   * narration transcript. The compiler ignores it; not needed on the first scene.
   */
  starts?: string
  /**
   * Optional. Anchor name → phrase spoken in this scene; `host.resolve(phrase)` turns the phrase into
   * seconds. Required only when a block uses an anchor name as its time; omit it when every time
   * is a number.
   */
  anchors?: Record<string, string>
  /** Blocks, top to bottom. */
  blocks: Block[]
  /**
   * Optional per-orientation gap between blocks (default 40); must be ≥ 0 and smaller than the safe-area height.
   * @default 40
   * @minimum 0
   */
  gap?: number | PerOrientation
  /**
   * Vertical placement of the block stack inside the safe area (default top).
   * @default "top"
   */
  valign?: "top" | "center"
}

/** A parsed scenes file: `{ scenes: SceneSpec[] }`. */
export type ScenesFile = { scenes: SceneSpec[] }
